examples.template:
MonarchButton({{trigger}}) { isOpen = true }
    .sheet(isPresented: $isOpen) {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            Text({{title}}).monarchTextStyle(.heading)
            Text({{description}}).monarchTextStyle(.body)
            Text({{body}}).monarchTextStyle(.body)
            HStack(spacing: theme.spacing.space2) {
                MonarchButton({{cancel}}) { isOpen = false }
                MonarchButton({{confirm}}, variant: .primary) { isOpen = false }
            }
        }
        .padding(theme.spacing.space6)
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
        .background(theme.colors.bgRaised)
        .presentationDetents([.medium, .large])
        .presentationDragIndicator(.visible)
    }

examples.code:
